import '../actions/action_registry.dart';
import '../actions/agent_action.dart';

const _header =
    '<!-- Generated by tool/action.dart --write-reference. Do not edit. -->';

/// Every action of [registry] as Markdown, sorted by name. Pure and
/// deterministic, so a test can compare it with the committed file.
String buildActionReference(ActionRegistry registry) {
  final out = StringBuffer()
    ..writeln(_header)
    ..writeln()
    ..writeln('# Actions');
  for (final action in registry.all) {
    out
      ..writeln()
      ..writeln('## ${action.name}')
      ..writeln()
      ..writeln(action.description.trim())
      ..writeln()
      ..writeln('Flags: ${_flags(action).join(' | ')}')
      ..writeln();
    final schema = action.input.toJsonSchema();
    final properties = schema['properties'];
    final required = {...?(schema['required'] as List<Object?>?)};
    if (properties is! Map<String, Object?> || properties.isEmpty) {
      out.writeln('No input.');
    } else {
      out
        ..writeln('| Field | Type | Required | Description |')
        ..writeln('|---|---|---|---|');
      for (final MapEntry(key: name, value: field) in properties.entries) {
        final spec = field is Map<String, Object?> ? field : const {};
        out.writeln(
          '| `$name` | ${_type(spec)} | ${required.contains(name) ? 'yes' : 'no'} '
          '| ${_cell('${spec['description'] ?? ''}')} |',
        );
      }
    }
    if (action.failureCodes.isNotEmpty) {
      out
        ..writeln()
        ..writeln(
          'Failure codes: ${action.failureCodes.map((c) => '`$c`').join(', ')}',
        );
    }
  }
  return '$out';
}

List<String> _flags(AgentAction<Object?, Object?> action) => [
  action.readOnly ? 'read-only' : 'writes ${action.resources.join(', ')}',
  ?switch (_needsApproval(action)) {
    true => 'needs approval',
    null => 'may need approval',
    false => null,
  },
  if (!action.agentTool) 'UI-only',
];

/// Whether the action asks for approval on a minimal valid input; null when
/// that input cannot be built or checked. An action that asks only for some
/// inputs may not show it.
bool? _needsApproval(AgentAction<Object?, Object?> action) {
  try {
    final sample = _sample(action.input.toJsonSchema());
    return action.needsApproval(action.input.parse(sample));
  } on Object {
    return null;
  }
}

/// The smallest value that satisfies a JSON Schema from the schema builder.
Object? _sample(Map<String, Object?> schema) => switch (schema['type']) {
  'object' => {
    for (final name in (schema['required'] as List<Object?>?) ?? const [])
      '$name': _sample(
        ((schema['properties'] as Map<String, Object?>)['$name']
            as Map<String, Object?>),
      ),
  },
  'string' => switch (schema['enum']) {
    final List<Object?> options when options.isNotEmpty => options.first,
    _ => 'x' * ((schema['minLength'] as int?) ?? 1).clamp(1, 1000),
  },
  'integer' => (schema['minimum'] as int?) ?? 0,
  'number' => (schema['minimum'] as num?) ?? 0,
  'boolean' => false,
  'array' => [
    for (var i = 0; i < ((schema['minItems'] as int?) ?? 0); i++)
      _sample(schema['items'] as Map<String, Object?>),
  ],
  _ => null,
};

String _type(Map<Object?, Object?> spec) => spec['type'] == 'array'
    ? 'array of ${_type(spec['items'] as Map<Object?, Object?>? ?? const {})}'
    : '${spec['type'] ?? 'any'}';

String _cell(String text) => text.replaceAll('|', r'\|').replaceAll('\n', ' ');
